import { Component } from '@angular/core';
import { AuthenticationService } from 'src/app/_services';
import { LoginRequestDto } from 'src/app/_models';
import { first } from 'rxjs';
import { Router } from '@angular/router';

@Component({
    selector: 'app-login',
    templateUrl: './login.component.html',
    styleUrls: ['./login.component.css']
})
export class LoginComponent {

    constructor(private authService: AuthenticationService,
		private router: Router) {}

    emailOrUsername: string = '';
    password: string = '';

    loginRequestData: LoginRequestDto = new LoginRequestDto('', '');

    login() {
        this.authService
            .login(this.loginRequestData)
            .pipe(first())
            .subscribe({
                next: (res) => {
                    console.log(res);
					alert('Successfully logged in');
					this.router.navigate(['/']);
                },
                error: (err) => {
                    console.log(err);
					alert('Error while logging in: ' + err);
                }
            });
    }
}
<div class="container d-flex flex-column align-items-center">
    <!-- logo svg -->
    <div class="d-flex flex-column align-items-center h-100 mainPage">
        <br /><br />
        <img src="assets/img/logo.svg" alt="logo" class="logo" />
        <br /><br />
        <input
            class="default-input"
            type="text"
            [(ngModel)]="loginRequestData.emailOrUsername"
            placeholder="Username Or Email"
        />
        <br /><br />
        <input
            class="default-input"
            type="password"
            [(ngModel)]="loginRequestData.password"
            placeholder="Password"
        />
        <br /><br />
        <button class="default-button" (click)="login()">Login</button>
        <br /><br /><br /><br />
        <a class="default-link" routerLink="/signup">Not a User? Sign Up</a>
    </div>
</div>
